using FluentAssertions;
using MasjidApp.Core.Configuration;
using MasjidApp.Core.Models;

namespace MasjidApp.Core.Tests.Configuration;

public sealed class TenantBrandingTests
{
    // Masjid ids are generated by each WordPress installation (e.g. "masjid-312fc341"),
    // so matching must depend on the config host alone, never on the id.
    private const string GeneratedMasjidId = "masjid-312fc341";

    [Theory]
    [InlineData("https://example.org/wp-json/masjid/v1/config")]
    [InlineData("https://notbothellmosque.org/config")]
    [InlineData("https://bothellmosque.org.evil.example/config")]
    public void Get_HostIsNotTheTenantWebsite_ReturnsNull(string url)
    {
        TenantBranding.Get(new MasjidStoredEntry(GeneratedMasjidId, "Islamic Center of Bothell", url))
            .Should().BeNull();
    }

    [Theory]
    [InlineData("https://bothellmosque.org/wp-json/masjid/v1/config", "icob", "ICOB")]
    [InlineData("https://api.bothellmosque.org/config", "icob", "ICOB")]
    [InlineData("https://mapsredmond.org/config", "maps", "MAPS")]
    [InlineData("https://api.mapsredmond.org/config", "maps", "MAPS")]
    public void Get_HostIsTheTenantWebsite_ReturnsBranding(string url, string id, string expectedIconName)
    {
        var branding = TenantBranding.Get(new MasjidStoredEntry(id, "Any Name", url));

        branding.Should().NotBeNull();
        branding!.IosAlternateIconName.Should().Be(expectedIconName);
    }
}
